using System;
using System.Collections.Generic;

namespace FluentMigrator.IdempotentExtensions.Tests;

/// <summary>
/// Unit tests for the SQL generated by the <c>UpdateDataIfRelated*</c> / <c>DeleteDataIfRelated*</c>
/// methods. Statements are captured from the migration expression without executing them.
/// </summary>
public sealed class RelatedRowsSqlTests
{
    [Fact]
    public void UpdateDataIfRelatedExists_L2ApiExample_SqlServer()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("documents",
                setValues: new Dictionary<string, object?> { ["is_visible_for_client"] = true },
                related: new RelatedRows("client_documents", new Dictionary<string, string> { ["document_id"] = "id" })
                {
                    NotNullColumns = ["client_id"],
                },
                keyValues: new Dictionary<string, object?> { ["is_visible_for_client"] = false }));

        Assert.Equal(
            "UPDATE [dbo].[documents] SET [is_visible_for_client] = 1 WHERE [is_visible_for_client] = 0 AND EXISTS (SELECT 1 FROM [dbo].[client_documents] WHERE [dbo].[client_documents].[document_id] = [dbo].[documents].[id] AND [dbo].[client_documents].[client_id] IS NOT NULL);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_L2ApiExample_Postgres()
    {
        var sql = SqlCapture.For("Postgres", m =>
            m.UpdateDataIfRelatedExists("documents",
                setValues: new Dictionary<string, object?> { ["is_visible_for_client"] = true },
                related: new RelatedRows("client_documents", new Dictionary<string, string> { ["document_id"] = "id" })
                {
                    NotNullColumns = ["client_id"],
                },
                keyValues: new Dictionary<string, object?> { ["is_visible_for_client"] = false }));

        Assert.Equal(
            "UPDATE \"public\".\"documents\" SET \"is_visible_for_client\" = TRUE WHERE \"is_visible_for_client\" = FALSE AND EXISTS (SELECT 1 FROM \"public\".\"client_documents\" WHERE \"public\".\"client_documents\".\"document_id\" = \"public\".\"documents\".\"id\" AND \"public\".\"client_documents\".\"client_id\" IS NOT NULL);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_TwoJoinColumns()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("orders",
                setValues: new Dictionary<string, object?> { ["status"] = "processed" },
                related: new RelatedRows("order_items", new Dictionary<string, string>
                {
                    ["order_id"] = "id",
                    ["tenant_id"] = "tenant_id"
                })));

        Assert.Equal(
            "UPDATE [dbo].[orders] SET [status] = 'processed' WHERE EXISTS (SELECT 1 FROM [dbo].[order_items] WHERE [dbo].[order_items].[order_id] = [dbo].[orders].[id] AND [dbo].[order_items].[tenant_id] = [dbo].[orders].[tenant_id]);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_RelatedWhereWithNull_IsNull()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("orders",
                setValues: new Dictionary<string, object?> { ["status"] = "archived" },
                related: new RelatedRows("order_items", new Dictionary<string, string> { ["order_id"] = "id" })
                {
                    Where = new Dictionary<string, object?> { ["deleted_at"] = null }
                },
                keyValues: new Dictionary<string, object?> { ["status"] = "completed" }));

        Assert.Equal(
            "UPDATE [dbo].[orders] SET [status] = 'archived' WHERE [status] = 'completed' AND EXISTS (SELECT 1 FROM [dbo].[order_items] WHERE [dbo].[order_items].[order_id] = [dbo].[orders].[id] AND [dbo].[order_items].[deleted_at] IS NULL);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_TargetNotNullColumns()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("orders",
                setValues: new Dictionary<string, object?> { ["status"] = "processed" },
                related: new RelatedRows("order_items", new Dictionary<string, string> { ["order_id"] = "id" }),
                keyValues: new Dictionary<string, object?> { ["status"] = "pending" },
                notNullColumns: ["processed_at"]));

        Assert.Equal(
            "UPDATE [dbo].[orders] SET [status] = 'processed' WHERE [status] = 'pending' AND [processed_at] IS NOT NULL AND EXISTS (SELECT 1 FROM [dbo].[order_items] WHERE [dbo].[order_items].[order_id] = [dbo].[orders].[id]);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedNotExists_GeneratesNotExists()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedNotExists("orders",
                setValues: new Dictionary<string, object?> { ["status"] = "orphaned" },
                related: new RelatedRows("order_items", new Dictionary<string, string> { ["order_id"] = "id" })));

        Assert.Equal(
            "UPDATE [dbo].[orders] SET [status] = 'orphaned' WHERE NOT EXISTS (SELECT 1 FROM [dbo].[order_items] WHERE [dbo].[order_items].[order_id] = [dbo].[orders].[id]);",
            sql);
    }

    [Fact]
    public void DeleteDataIfRelatedExists_GeneratesDelete()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.DeleteDataIfRelatedExists("orders",
                related: new RelatedRows("order_items", new Dictionary<string, string> { ["order_id"] = "id" }),
                keyValues: new Dictionary<string, object?> { ["status"] = "cancelled" }));

        Assert.Equal(
            "DELETE FROM [dbo].[orders] WHERE [status] = 'cancelled' AND EXISTS (SELECT 1 FROM [dbo].[order_items] WHERE [dbo].[order_items].[order_id] = [dbo].[orders].[id]);",
            sql);
    }

    [Fact]
    public void DeleteDataIfRelatedNotExists_GeneratesDeleteWithNotExists()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.DeleteDataIfRelatedNotExists("orders",
                related: new RelatedRows("order_items", new Dictionary<string, string> { ["order_id"] = "id" }),
                keyValues: (IReadOnlyDictionary<string, object?>?)null));

        Assert.Equal(
            "DELETE FROM [dbo].[orders] WHERE NOT EXISTS (SELECT 1 FROM [dbo].[order_items] WHERE [dbo].[order_items].[order_id] = [dbo].[orders].[id]);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_ExplicitSchemaName()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("documents",
                setValues: new Dictionary<string, object?> { ["flag"] = true },
                related: new RelatedRows("client_documents", new Dictionary<string, string> { ["document_id"] = "id" }, schemaName: "crm"),
                schemaName: "app"));

        Assert.Equal(
            "UPDATE [app].[documents] SET [flag] = 1 WHERE EXISTS (SELECT 1 FROM [crm].[client_documents] WHERE [crm].[client_documents].[document_id] = [app].[documents].[id]);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_AnonymousObjects()
    {
        var sql = SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("documents",
                setValues: new { is_visible_for_client = true },
                related: new RelatedRows("client_documents", new Dictionary<string, string> { ["document_id"] = "id" })
                {
                    NotNullColumns = ["client_id"],
                },
                keyValues: new { is_visible_for_client = false }));

        Assert.Equal(
            "UPDATE [dbo].[documents] SET [is_visible_for_client] = 1 WHERE [is_visible_for_client] = 0 AND EXISTS (SELECT 1 FROM [dbo].[client_documents] WHERE [dbo].[client_documents].[document_id] = [dbo].[documents].[id] AND [dbo].[client_documents].[client_id] IS NOT NULL);",
            sql);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_EmptySetValues_Throws()
    {
        var ex = Assert.Throws<ArgumentException>(() => SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("orders",
                setValues: new Dictionary<string, object?>(),
                related: new RelatedRows("order_items", new Dictionary<string, string> { ["order_id"] = "id" }))));

        Assert.Equal("setValues", ex.ParamName);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_EmptyJoinColumns_Throws()
    {
        var ex = Assert.Throws<ArgumentException>(() => SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("orders",
                setValues: new Dictionary<string, object?> { ["status"] = "x" },
                related: new RelatedRows("order_items", new Dictionary<string, string>()))));

        Assert.Equal("joinColumns", ex.ParamName);
    }

    [Fact]
    public void UpdateDataIfRelatedExists_WhereAndNotNullOverlap_Throws()
    {
        var ex = Assert.Throws<ArgumentException>(() => SqlCapture.For("SqlServer", m =>
            m.UpdateDataIfRelatedExists("orders",
                setValues: new Dictionary<string, object?> { ["status"] = "x" },
                related: new RelatedRows("order_items", new Dictionary<string, string> { ["order_id"] = "id" })
                {
                    Where = new Dictionary<string, object?> { ["client_id"] = 1 },
                    NotNullColumns = ["client_id"]
                })));

        Assert.Equal("related", ex.ParamName);
        Assert.Contains("client_id", ex.Message);
    }

    [Theory]
    [InlineData("SqlServer")]
    [InlineData("Postgres")]
    [InlineData("MySql")]
    [InlineData("SQLite")]
    [InlineData("Oracle")]
    public void UpdateDataIfRelatedExists_SelfReference_Throws(string databaseType)
    {
        var ex = Assert.Throws<ArgumentException>(() => SqlCapture.For(databaseType, m =>
            m.UpdateDataIfRelatedExists("orders",
                setValues: new Dictionary<string, object?> { ["status"] = "x" },
                related: new RelatedRows("orders", new Dictionary<string, string> { ["parent_id"] = "id" }))));

        Assert.Equal("related", ex.ParamName);
    }
}
